<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { Search, Truck } from 'lucide-vue-next';
import { api } from '../api';
import { label, params, stamp, useMonitoringOptions, type PageResult } from '../province-monitoring';
import { useSessionStore } from '../stores/session';
import QueryPanel from '../components/QueryPanel.vue';
import QueryField from '../components/QueryField.vue';
import ProvinceVehicleDrawer from '../components/ProvinceVehicleDrawer.vue';
import ProvincePageState from '../components/ProvincePageState.vue';
import '../province-monitoring.css';
const route = useRoute(), router = useRouter(), session = useSessionStore(), { options, loadOptions } = useMonitoringOptions();
const rows = ref<any[]>([]), total = ref(0), page = ref(1), q = ref(''), workspaceId = ref(''), enterpriseId = ref(''), vehicleType = ref(''), licenseState = ref(''), loading = ref(false), error = ref(''), drawer = ref(false), selectedId = ref(''), tab = ref('overview');
const enterprises = computed(() => options.value.enterprises.filter(row => !workspaceId.value || row.workspaceId === workspaceId.value));
let generation = 0, controller: AbortController | undefined;
function values() { return { q: q.value.trim(), workspaceId: workspaceId.value, enterpriseId: enterpriseId.value, vehicleType: vehicleType.value, licenseState: licenseState.value, page: page.value }; }
async function load() { const current = ++generation; controller?.abort(); controller = new AbortController(); loading.value = true; error.value = ''; try { if (!options.value.workspaces.length) await loadOptions(); const result = await api<PageResult>(`/province/vehicles?${params(values())}`, { signal: controller.signal }); if (current === generation) { rows.value = result.items; total.value = result.total; } } catch (reason) { if (current === generation && !controller.signal.aborted) error.value = reason instanceof Error ? reason.message : '车辆档案列表读取失败'; } finally { if (current === generation) loading.value = false; } }
function search(reset = true) { if (reset) page.value = 1; drawer.value = false; void router.replace({ path: '/province/vehicles', query: Object.fromEntries(params(values())) }); if (route.fullPath === `/province/vehicles?${params(values())}`) void load(); }
function open(id: string, view = 'overview') { selectedId.value = id; tab.value = view; drawer.value = true; void router.replace({ path: '/province/vehicles', query: { ...Object.fromEntries(params(values())), vehicleId: id, tab: view } }); }
function reset() { q.value = workspaceId.value = enterpriseId.value = vehicleType.value = licenseState.value = ''; search(); }
function close(value: boolean) { drawer.value = value; if (!value && route.query.vehicleId) { const { vehicleId: _id, tab: _tab, ...query } = route.query; void router.replace({ path: route.path, query }); } }
function setTab(value: string) { tab.value = value; if (drawer.value) void router.replace({ path: route.path, query: { ...route.query, tab: value } }); }
let listQuery = '';
watch(() => route.query, query => { q.value = String(query.q ?? ''); workspaceId.value = String(query.workspaceId ?? ''); enterpriseId.value = String(query.enterpriseId ?? ''); vehicleType.value = String(query.vehicleType ?? ''); licenseState.value = String(query.licenseState ?? ''); page.value = Math.max(1, Number(query.page) || 1); const key = String(params(values())); if (key !== listQuery) { listQuery = key; void load(); } if (typeof query.vehicleId === 'string') { selectedId.value = query.vehicleId; tab.value = String(query.tab ?? 'overview'); drawer.value = true; } else drawer.value = false; }, { immediate: true });
onBeforeUnmount(() => { generation++; controller?.abort(); });
</script>
<template><section class="pm-page pm-fill-page"><h1 class="sr-only">车辆监管档案</h1><QueryPanel :loading="loading" @search="search()" @reset="reset"><QueryField label="所属地市"><el-select v-model="workspaceId" aria-label="所属地市" clearable placeholder="全部地市" @change="enterpriseId = ''; search()"><el-option v-for="city in options.workspaces" :key="city.id" :label="city.cityName" :value="city.id"/></el-select></QueryField><QueryField label="运营企业"><el-select v-model="enterpriseId" aria-label="运营企业" clearable filterable placeholder="全部企业"><el-option v-for="row in enterprises" :key="row.id" :value="row.id" :label="row.name"/></el-select></QueryField><QueryField label="车辆编号 / VIN" keyword><el-input v-model="q" aria-label="车辆编号 / VIN" :prefix-icon="Search" clearable placeholder="编号 / 统一编码 / VIN / 设备编号"/></QueryField><QueryField label="车辆用途"><el-select v-model="vehicleType" aria-label="车辆用途" clearable placeholder="全部用途"><el-option v-for="type in ['DELIVERY','SANITATION','PATROL','RETAIL','SHUTTLE','OTHER']" :key="type" :value="type" :label="label(type)"/></el-select></QueryField><QueryField v-if="session.user?.permissions.includes('admission:license:read')" label="许可状态"><el-select v-model="licenseState" aria-label="许可状态" clearable placeholder="全部许可状态"><el-option label="许可有效" value="VALID"/><el-option label="无有效许可" value="EXPIRED"/><el-option label="未办理许可" value="NONE"/></el-select></QueryField></QueryPanel><ProvincePageState class="pm-fill-body" :error="error" :loading="loading" @retry="load"><section class="pm-list-surface" aria-label="车辆监管档案列表"><el-table :data="rows" height="100%" row-key="id" :row-class-name="({ row }: any) => row.id === selectedId ? 'pm-selected-row' : ''" empty-text="没有符合条件的车辆档案"><el-table-column label="车辆档案" min-width="270"><template #default="{ row }"><div class="pm-vehicle-cell"><span class="pm-truck-avatar"><Truck :size="25"/></span><div><el-button link type="primary" @click="open(row.id)">{{ row.businessNo }}</el-button><small class="pm-subline">{{ row.unifiedCode || row.vin }}</small></div></div></template></el-table-column><el-table-column prop="cityName" label="所属地市" width="110"/><el-table-column label="运营企业" min-width="220"><template #default="{ row }">{{ row.enterprise.name }}</template></el-table-column><el-table-column label="车型 / 用途" min-width="180"><template #default="{ row }">{{ row.model.name }}<small class="pm-subline">{{ label(row.vehicleType) }}</small></template></el-table-column><el-table-column v-if="session.user?.permissions.includes('admission:license:read')" label="许可状态" width="130"><template #default="{ row }"><el-tag :type="row.licenses?.some((l: any) => l.status === 'VALID' && new Date(l.expiresAt) > new Date()) ? 'success' : 'info'" effect="plain">{{ row.licenses?.some((l: any) => l.status === 'VALID' && new Date(l.expiresAt) > new Date()) ? '许可有效' : row.licenses?.length ? '无有效许可' : '未办理许可' }}</el-tag></template></el-table-column><el-table-column label="最后上报" width="135"><template #default="{ row }">{{ stamp(row.realtimeStatus?.heartbeatAt) }}</template></el-table-column><el-table-column label="操作" width="180" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="open(row.id)">查看档案</el-button><el-button v-if="session.user?.permissions.includes('operation:trajectory:read')" link type="primary" @click="open(row.id, 'tracks')">运行轨迹</el-button></template></el-table-column></el-table><footer class="pm-pagination"><span>共 {{ total }} 辆车辆</span><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="prev,pager,next" @current-change="search(false)"/></footer></section></ProvincePageState><ProvinceVehicleDrawer :model-value="drawer" :vehicle-id="selectedId" :workspace-id="workspaceId" :initial-tab="tab" @update:model-value="close" @tab="setTab"/></section></template>


